// === Tab: main.js ===
"use strict";
/*
Splash!

When a particle exceeds a certain velocity it splits to new particles to create a water effect.

Controls:
  - Move the mouse over the word.

Author:
  Jason Labbe

Site:
  jasonlabbe3d.com

Modifications:
  * refactored for readability while learning
  * have camera shake fueled by bursting particles
	    * todo: have a % of camera shake accelerate the particles - really, world shake, not camera shake.
  */

let word = "QUASAR INSTITUTE";
let font;
let tPoints;

const particles = [];
let velThreshold = 4;
let splitCount = 5;

let h = 300;
let minh = 200;
let maxh = 300;

let sizeOfText = 150;

// When a particle bursts, we will boost this.  It decays over time.
let screenShakeAmplitude = 0;

function preload() {
	font = loadFont("https://openprocessing.org/sketch/1193561/files/AvenirNextLTPro-Demi.otf");
}


function setup() {
	createCanvas(1920, 1080);

	colorMode(HSB, 255);

	// Get positions to assign particles to.
	tPoints = font.textToPoints(word, width / 2, height / 2, sizeOfText, {
		sampleFactor: 0.6
	});

	// Try to find out the text's width to offset it to the scene's center.
	let start = tPoints[0].x;
	let end = tPoints[tPoints.length - 1].x;
	let centerX = (start - end) * 0.5;

	// Create particles.
	createParticles(centerX);

	background(0);
}

function draw() {
	background(0, 50);


	const shake = p5.Vector.random2D().mult(
		random(0, screenShakeAmplitude));

	translate(shake.x, shake.y);

	//draw a ground plane for reference
	noStroke();
	fill(20);
	rect(-2000, height * 0.66, width + 2000, height * 0.66);

	for (let i = particles.length - 1; i > -1; i--) {
		let p = particles[i];

		p.move();

		if (p.isActivated) {
			stroke(p.pColor);
		} else {
			stroke(120, p.vel.mag() * 50, 255); // Turns blue the more it moves.
		}

		strokeWeight(p.pSize);

		point(p.pos.x, p.pos.y);

		// Remove particles that are out of bounds.
		if (p.pos.y > height || p.pos.x < 0 || p.pos.x > width) {
			particles.splice(i, 1);
		}
	}
	decayScreenShake();
}

function increaseScreenShake() {
	screenShakeAmplitude += 0.4;
}

function decayScreenShake() {
	screenShakeAmplitude -= 1;
	if (screenShakeAmplitude < 0) {
		screenShakeAmplitude = 0;
	}
}



function createParticles(centerX) {
	for (let i = 0; i < tPoints.length; i++) {
		let j = int(random(tPoints.length));
		particles.push(new Particle(
			tPoints[j].x + centerX,
			tPoints[j].y,
			tPoints[j].x + centerX,
			tPoints[j].y));
	}
}

// === Tab: particle.js ===
//todo: switch movement function when activated
function Particle(x, y, tx, ty) {

  this.pos = new p5.Vector(x, y);
  this.vel = new p5.Vector(0, 0);
  this.acc = new p5.Vector(0, 0);
  this.target = new p5.Vector(tx, ty);
  this.isActivated = false;
  this.fallVariance = random(0.75, 1.25);
  this.pColor = color(255);
  this.pSize = 1;


  this.move = function () {
    if (!this.isActivated) {
      if (this.vel.mag() > velThreshold) {
        this.burstAndActivate();
      } else {
        this.applyTargetSeeking();
      }
    } else {
      this.applyGravity();
    }
    //in all cases...
    this.applyFleeingFromMouse();

    // Move it.
    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }


  this.applyGravity = function () {
    this.acc.add(new p5.Vector(0, 0.2 * this.fallVariance));
  }


  this.applyTargetSeeking = function () {

    // If its velocity didn't exceed the threshold then seek its target.
    let targetDist = dist(this.pos.x, this.pos.y, this.target.x, this.target.y);

    let proximityMult = 1;

    // Slow it down the closer it gets to its target.
    let distThresh = 50;
    if (targetDist < distThresh) {
      proximityMult = targetDist / distThresh;
    }

    // Add some friction so it can eventually settle.
    this.vel.mult(0.99);

    // Seek its target.
    if (targetDist > 1) {
      let steer = new p5.Vector(this.target.x, this.target.y);
      steer.sub(this.pos);
      steer.normalize();
      steer.mult(0.05 * proximityMult);
      this.acc.add(steer);
    }
  }


  this.burstAndActivate = function () {
    // Activates if its velocity exceeds the threshold.
    this.isActivated = true;
		increaseScreenShake();
    // Spawn a few more particles in place for a nice effect.
    for (let i = 0; i < splitCount; i++) {
      var p = new Particle(this.pos.x, this.pos.y, this.target.x, this.target.y);

      p.isActivated = true;
      p.vel.set(this.vel.x, this.vel.y);
      p.vel.mult(random(0.9, 1.1));
      p.vel.rotate(radians(random(-25, 25)));
      p.acc.set(this.acc.x, this.acc.y);
      p.pSize = random(0.25, 3);

      // Keep the last particle white.
      if (i < splitCount - 1) {
        p.pColor = color(h, 255, 255);
      }

      particles.push(p);

      // Increase hue for the next particle.
      h += 0.1;
      if (h > maxh) {
        h = minh;
      }
    }
  }


  this.applyFleeingFromMouse = function () {
    // Push it away from the mouse.
    let mouseDist = dist(this.pos.x, this.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let mouseThresh = 100;

    if (mouseDist < mouseThresh) {
      let push = new p5.Vector(this.pos.x, this.pos.y);
      push.sub(new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
      push.normalize();
      push.mult((mouseThresh - mouseDist) * 0.0025);
      this.acc.add(push);
    }
  }
}

